    eor x4, x4, x9
    mov x5, v8.d[1]
    stp x4, x5, [x3]
    add sp, sp, #16
    RESTORE_SIMD_CALLEE
    ret
END_KERNEL stress_k_mixed

// ---------------------------------------------------------------------------
// C8 / C9: FP32 FMA streaming its operands from a large buffer, so the
// caches (C8, L2-sized) or DRAM and the memory controller (C9) work too.
// Each 64-byte step loads A (8 floats) and B (8 floats): 16 vector FMAs =
// 128 FLOP, i.e. 2 FLOP per byte. One iteration = one pass over the buffer.
// Mirrored buffer as in C2.
// ---------------------------------------------------------------------------
KERNEL stress_k_fp32_stream
    SAVE_SIMD_CALLEE
    movi v8.16b, #0
    movi v9.16b, #0
    movi v10.16b, #0
    movi v11.16b, #0
    movi v12.16b, #0
    movi v13.16b, #0
    movi v14.16b, #0
    movi v15.16b, #0
    movi v16.16b, #0
    movi v17.16b, #0
    movi v18.16b, #0
    movi v19.16b, #0
    movi v20.16b, #0
    movi v21.16b, #0
    movi v22.16b, #0
    movi v23.16b, #0
    lsr x7, x2, #6
1:
    mov x5, x1
    mov x6, x7
2:
    ldp q2, q3, [x5, #32]
    ldp q0, q1, [x5], #64
    fmla v8.4s, v0.4s, v2.s[0]
    fmla v9.4s, v0.4s, v2.s[1]
    fmla v10.4s, v0.4s, v2.s[2]
    fmla v11.4s, v0.4s, v2.s[3]
    fmla v12.4s, v0.4s, v3.s[0]
    fmla v13.4s, v0.4s, v3.s[1]
    fmla v14.4s, v0.4s, v3.s[2]
    fmla v15.4s, v0.4s, v3.s[3]
    fmla v16.4s, v1.4s, v2.s[0]
    fmla v17.4s, v1.4s, v2.s[1]
    fmla v18.4s, v1.4s, v2.s[2]
    fmla v19.4s, v1.4s, v2.s[3]
    fmla v20.4s, v1.4s, v3.s[0]
    fmla v21.4s, v1.4s, v3.s[1]
    fmla v22.4s, v1.4s, v3.s[2]
    fmla v23.4s, v1.4s, v3.s[3]
    subs x6, x6, #1
    b.ne 2b
    subs x0, x0, #1
    b.ne 1b
    eor v8.16b, v8.16b, v9.16b
    eor v8.16b, v8.16b, v10.16b
    eor v8.16b, v8.16b, v11.16b
    eor v8.16b, v8.16b, v12.16b
    eor v8.16b, v8.16b, v13.16b
    eor v8.16b, v8.16b, v14.16b
    eor v8.16b, v8.16b, v15.16b
    eor v8.16b, v8.16b, v16.16b
    eor v8.16b, v8.16b, v17.16b
    eor v8.16b, v8.16b, v18.16b
    eor v8.16b, v8.16b, v19.16b
    eor v8.16b, v8.16b, v20.16b
    eor v8.16b, v8.16b, v21.16b
    eor v8.16b, v8.16b, v22.16b
    eor v8.16b, v8.16b, v23.16b
    str q8, [x3]
    RESTORE_SIMD_CALLEE
    ret
END_KERNEL stress_k_fp32_stream
